	public void SetParryCheckStatus(BoolVarStatMod givenMod, bool givenStatus)
	{
		if (givenMod != null)
		{
			parryAvailStat.Modify(givenMod, givenStatus);
			Health health = base.health;
			health.takeDamageEnterHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEnterHandlers, new Health.OnTakeDamageHandler(CheckForParry));
			if (parryAvailStat.CurrentValue)
			{
				Health health2 = base.health;
				health2.takeDamageEnterHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health2.takeDamageEnterHandlers, new Health.OnTakeDamageHandler(CheckForParry));
			}
		}
	}

	private void CheckForParry(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (givenAtkInfo == null || givenAtkInfo.isStatusEffect || health.GuardNextAtk || (!(fsm.currentState is BaseDashState) && !(currentStateName == SlideState.staticID) && !(currentStateName == ParryState.staticID) && !(currentStateName == "Idle") && (!parryActive || !(currentStateName == "Run"))))
		{
			return;
		}
		parryInputVec = GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false);
		if (!(Vector2.Angle(parryInputVec, -givenAtkInfo.attackingVector) > 50f))
		{
			health.GuardNextAtk = true;
			PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, givenAtkInfo.attackerPosition, givenAtkInfo.targetPosition);
			CameraController.ShakeCamera(0.1f);
			TimeScaleController.SetTimeScaleDelayOverRealTime(0.0625f, 0.01f, useEaseOut: true, ignoreAllPrevDelays: true);
			movement.dashVector = -parryInputVec;
			fsm.ChangeState(ParryState.staticID, allowSelfTransition: true);
			if (parryEventHandlers != null)
			{
				parryEventHandlers(givenAtkInfo, parryInputVec);
			}
		}
	}

	public bool HasSkillType(SkillApplyCondition givenCondition)
	{
		for (int i = 0; i < 6; i++)
		{
			if (givenCondition(assignedSkills[i]))
			{
				return true;
			}
		}
		return false;
	}

	public bool TransitionToSkill(int skillNo, bool checkButtonHeld = false)
	{
		if ((!checkButtonHeld) ? inputDevice.GetButtonDown("Skill" + skillNo) : inputDevice.GetButton("Skill" + skillNo))
		{
			return assignedSkills[skillNo] != null && assignedSkills[skillNo].Transition();
		}
		return false;
	}

	public bool HandleSkills(bool allowButtonHeld = false, string ignoreStr = "")
	{
		for (int i = 0; i < 6; i++)
		{
			if (assignedSkills[i] != null && !(assignedSkills[i].name == ignoreStr) && TransitionToSkill(i, allowButtonHeld))
			{
				return true;
			}
		}
		return false;
	}
}

using System.Collections.Generic;

public class DoTManager
{
	private Entity entity;

	public Dictionary<string, DoTEffect> dotDict;

	private List<string> dotIDList;

	public int ActiveDotCount => dotDict.Values.Count;

	public DoTManager(Entity newEntity)
	{
		dotDict = new Dictionary<string, DoTEffect>();
		dotIDList = new List<string>();
		entity = newEntity;
	}

	public void Update()
	{
		if (dotDict.Count == 0)
		{
			return;
		}
		dotIDList.AddRange(dotDict.Keys);
		for (int num = dotIDList.Count - 1; num >= 0; num--)
		{
			if (!DotIsActive(dotIDList[num]))
			{
				AnnounceStatusEvent(dotDict[dotIDList[num]], givenStatus: false);
				dotDict.Remove(dotIDList[num]);
			}
		}
		dotIDList.Clear();
	}

	public bool HasDot(string dotID)
	{
		return dotDict.ContainsKey(dotID) && dotDict[dotID] != null;
	}

	public bool DotIsActive(string givenID)
	{
		return HasDot(givenID) && !dotDict[givenID].Update();
	}

	public void AddDot(DoTEffect newDot)
	{
		if (HasDot(newDot.ID))
		{
			if (dotDict[newDot.ID].skillLevel <= newDot.skillLevel)
			{
				dotDict[newDot.ID].skillLevel = newDot.skillLevel;
				dotDict[newDot.ID].InitDotVars();
				dotDict[newDot.ID].Refresh(newDot.hitCount, newDot.damageInterval);
				AnnounceStatusEvent(newDot, givenStatus: true);
			}
		}
		else
		{
			dotDict[newDot.ID] = newDot;
			newDot.Init();
			AnnounceStatusEvent(newDot, givenStatus: true);
		}
	}

	public void RemoveDot(string givenID)
	{
		if (HasDot(givenID))
		{
			dotDict[givenID].Stop();
		}
	}

	public void ApplyStopElement(ElementType givenElement)
	{
		switch (givenElement)
		{
		case ElementType.Fire:
			RemoveDot(SlowDotEffect.slowStatusStr);
			break;
		case ElementType.Air:
			RemoveDot(PoisonDotEffect.poisonStatusStr);
			break;
		case ElementType.Earth:
			RemoveDot(ShockDotEffect.shockStatusStr);
			break;
		case ElementType.Lightning:
			if (entity != null && entity.fsm != null && entity.fsm.currentStateName == "Frozen")
			{
				entity.fsm.QueueChangeState(entity.fsm.defaultStateName);
			}
			break;
		case ElementType.Water:
			RemoveDot(BurnDoTEffect.burnStatusStr);
			break;
