using UnityEngine;

public class DoTEffect
{
	public int skillLevel;

	public StatData statData;

	public int damageStopwatchID;

	public float damageInterval;

	public bool useInterval = true;

	public int hitCount;

	public string ID;

	public string category;

	public AttackInfo atkInfo;

	public bool applyInstantly;

	public Entity parentEntity;

	public Entity attackEntity;

	public bool isBuff;

	private bool firstHit;

	private bool baseShowDamageEffect;

	public string sfxName = string.Empty;

	public bool randomFacingDir;

	public ElementType dotElement = ElementType.Neutral;

	public DoTEffect(string skillCat, string skillID, int newSkillLevel, Entity hurtEntity, Entity attackerEntity, bool instant = true)
	{
		ID = skillID;
		category = skillCat;
		statData = StatManager.GetSkillData(category, ID);
		skillLevel = newSkillLevel;
		parentEntity = hurtEntity;
		attackEntity = attackerEntity;
		applyInstantly = instant;
	}

	public virtual bool Update()
	{
		if (atkInfo == null || parentEntity == null || parentEntity.health == null || parentEntity.health.healthStat.CurrentValue <= 0f)
		{
			CleanUp();
			return true;
		}
		switch (ChaosStopwatch.CheckInterval(damageStopwatchID))
		{
		case StopwatchState.Running:
			return false;
		case StopwatchState.Ready:
			atkInfo.showDamageEffect = baseShowDamageEffect && (!firstHit || !applyInstantly);
			firstHit = false;
			atkInfo.attackerPosition = parentEntity.hurtBoxTransform.position;
			if (randomFacingDir)
			{
				atkInfo.attackerPosition = Random.insideUnitCircle;
				atkInfo.knockbackVector = -atkInfo.attackerPosition * atkInfo.knockbackMultiplier;
			}
			parentEntity.health.TakeDamage(atkInfo, attackEntity, critPreCalculated: true);
			if (sfxName != string.Empty)
			{
				SoundManager.PlayAudioWithDistance(sfxName, parentEntity.transform.position);
			}
			OnDamageTick();
			return false;
		case StopwatchState.Done:
			CleanUp();
			return true;
		default:
			return true;
		}
	}

	public virtual void Init()
	{
		InitDotVars();
	}

	public virtual void InitDotVars()
	{
		if (statData != null)
		{
			firstHit = true;
			skillLevel = Mathf.Clamp(skillLevel, 1, 5);
			atkInfo = AttackInfo.GetInfoFromData(attackEntity, statData, skillLevel, givenUlt: false);
			baseShowDamageEffect = atkInfo.showDamageEffect;
			damageInterval = statData.GetValue<float>(StatData.intervalStr, skillLevel);
			hitCount = (int)(statData.GetValue<float>(StatData.durStr, skillLevel) / damageInterval);
			damageStopwatchID = ChaosStopwatch.Begin((!applyInstantly) ? damageInterval : 0f, useInterval, damageInterval, hitCount);
		}
	}

	public virtual void CleanUp()
	{
	}

	public virtual void Refresh(int hits = 0, float time = 0f)
	{
		if (useInterval)
		{
			int num = ((hits != 0) ? hits : hitCount);
			if (ChaosStopwatch.GetRemainingIntervals(damageStopwatchID) < num)
			{
				ChaosStopwatch.RefreshIntervals(damageStopwatchID, num);
			}
		}
		else
		{
			ChaosStopwatch.Refresh(damageStopwatchID, (time != 0f) ? time : damageInterval);
		}
	}

	public virtual void Stop()
	{
		ChaosStopwatch.Stop(damageStopwatchID);
	}

	public virtual void OnDamageTick()
	{
	}
}

