	public void UpdateAttackHistory(string givenKey, AttackInfo givenAtkInfo)
	{
		if (!attackHistory.ContainsKey(givenKey))
		{
			attackHistory[givenKey] = new FixedSizeQueue<AttackInfo>(15);
		}
		attackHistory[givenKey].Enqueue(givenAtkInfo);
	}

	public bool CheckAttackHistory(int targetObjID)
	{
		if (!attackHistory.ContainsKey(atkInfo.attackInfoKey))
		{
			return true;
		}
		sameTargetTimeVal = atkInfo.sameTargetImmunityTime;
		sameAttackTimeVal = atkInfo.sameAttackImmunityTime;
		atkHistQueue = attackHistory[atkInfo.attackInfoKey];
		if (sameTargetTimeVal > 0f)
		{
			if (sameAttackTimeVal > 0f)
			{
				for (int num = 14; num >= 0; num--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID)
					{
						timeDiff = Time.time - atkHistInfo.time;
						if (sameTargetTimeVal > timeDiff || (sameAttackTimeVal > timeDiff && atkHistInfo.atkObjID == AttackerObjID))
						{
							return false;
						}
					}
				}
			}
			else
			{
				for (int num2 = 14; num2 >= 0; num2--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num2);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameTargetTimeVal > Time.time - atkHistInfo.time)
					{
						return false;
					}
				}
			}
		}
		else if (sameAttackTimeVal > 0f)
		{
			for (int num3 = 14; num3 >= 0; num3--)
			{
				atkHistInfo = atkHistQueue.GetAtIndex(num3);
				if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameAttackTimeVal > Time.time - atkHistInfo.time && atkHistInfo.atkObjID == AttackerObjID)
				{
					return false;
				}
			}
		}
		return true;
	}

	public AttackInfo GenerateAttackInfo(StatData curStatData, int skillLevel, bool isUltimate)
	{
		if (curStatData == null)
		{
			return null;
		}
		if (curStatData.category.Contains("Player"))
		{
			if (curStatData.category.EndsWith("0"))
			{
				generatedEntity = GameController.playerScripts[0];
			}
			else if (curStatData.category.EndsWith("1"))
			{
				generatedEntity = GameController.playerScripts[1];
			}
		}
		else
		{
			generatedEntity = entityScript;
		}
		generatedAtkInfo = AttackInfo.GetInfoFromData(generatedEntity, curStatData, skillLevel, isUltimate);
		generatedAtkInfo.knockbackOverwrite = !disableKnockbackOverwrite && generatedAtkInfo.knockbackOverwrite;
		generatedAtkInfo.attacker = attackerName;
		generatedAtkInfo.atkObjID = AttackerObjID;
		if (entityScript != null)
		{
			generatedAtkInfo.gameObject = entityScript.gameObject;
		}
		else if (transform.parent != null)
		{
			generatedAtkInfo.gameObject = transform.parent.gameObject;
		}
		else
		{
			generatedAtkInfo.gameObject = gameObject;
		}
		return generatedAtkInfo;

