using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class MeleeAttackObject : MonoBehaviour
{
	[HideInInspector]
	public Animator anim;

	[HideInInspector]
	public SpriteRenderer sprite;

	[HideInInspector]
	public Attack attack;

	[HideInInspector]
	public Collider2D attackCol;

	[HideInInspector]
	public Vector2 attackVec;

	[HideInInspector]
	public NegateProjectiles negateScript;

	public bool useAnimTime;

	public float endAnimTime = 1f;

	public bool useLifeTime;

	public float lifeTime = 1f;

	public string audioID = string.Empty;

	[HideInInspector]
	public int lifeStopwatchID;

	[HideInInspector]
	public bool collisionOccurred;

	public virtual void Awake()
	{
		anim = GetComponent<Animator>();
		if (transform.Find("Sprite") != null)
		{
			sprite = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		}
		if (transform.Find("AttackBox") != null)
		{
			this.attack = transform.Find("AttackBox").GetComponent<Attack>();
			Attack attack = this.attack;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(CheckCollision));
			Attack attack2 = this.attack;
			attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(CheckCollision));
			attackCol = this.attack.gameObject.GetComponent<Collider2D>();
			negateScript = this.attack.transform.GetComponent<NegateProjectiles>();
		}
		if (useLifeTime)
		{
			lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		}
		collisionOccurred = false;
	}

	public virtual void Start()
	{
		if (audioID != string.Empty)
		{
			SoundManager.PlayWithDistAndSPR(audioID, transform.position);
		}
	}

	public virtual void Update()
	{
		if ((useAnimTime && anim.AnimPlayed(endAnimTime)) || (useLifeTime && ChaosStopwatch.Check(lifeStopwatchID)))
		{
			EndAttack();
		}
	}

	public virtual void EndAttack()
	{
		if (this.attack != null)
		{
			Attack attack = this.attack;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(CheckCollision));
		}
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}

	public virtual void CheckCollision(Collider2D col)
	{
		if (!collisionOccurred)
		{
			collisionOccurred = true;
		}
	}

	public void ChangeAttackLevel(int newLevel)
	{
		if (attack != null)
		{
			attack.ChangeAttackInfoLevel(newLevel);
		}
	}

	public void IncrementAttackLevel()
	{
		if (attack != null && attack.atkInfo != null)
		{
			ChangeAttackLevel(attack.atkInfo.skillLevel + 1);
		}
	}
}
