using UnityEngine;

public class CreepingTendrilDotEffect : DoTEffect
{
	private static GameObject prefab;

	public BaseEffect effect;

	private WaterDropEmitter currentWDEmitter;

	private Vector2 emitPosition;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/CreepingTendrilEffect.prefab"));

	public CreepingTendrilDotEffect(string skillCat, string skillID, int newSkillLevel, Entity parentEntity, Entity attackEntity)
		: base(skillCat, skillID, newSkillLevel, parentEntity, attackEntity, instant: false)
	{
		dotElement = ElementType.Water;
	}

	public override void Init()
	{
		base.Init();
		effect = Globals.ChaosInst<BaseEffect>(Prefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
		effect.entity = parentEntity;
		if (GameController.pvpOn && parentEntity is Player)
		{
			damageStopwatchID = ChaosStopwatch.Begin(damageInterval, useInterval, damageInterval, Mathf.CeilToInt((float)hitCount * 0.5f));
		}
		if (Globals.RandBool)
		{
			effect.transform.localScale = new Vector3(-1f, 1f, 1f);
		}
	}

	public override void CleanUp()
	{
		effect.Disable();
		emitPosition = effect.transform.position;
		currentWDEmitter = PoolManager.GetPoolItem<WaterDropEmitter>();
		currentWDEmitter.Emit(5, emitPosition);
		currentWDEmitter.Emit(3, emitPosition + Vector2.up);
		currentWDEmitter.Emit(3, emitPosition + Vector2.down);
	}
}
